import json,sys,re
from datetime import datetime
path=sys.argv[1]
rows=[]
for line in open(path):
    line=line.strip()
    if not line: continue
    try: rows.append(json.loads(line))
    except: pass
def ts(r):
    t=r.get('timestamp')
    if not t: return None
    try: return datetime.fromisoformat(t.replace('Z','+00:00'))
    except: return None
times=[ts(r) for r in rows if ts(r)]
print(f"=== {path.split('/')[-1]}  entries={len(rows)} span={times[0] if times else '?'} -> {times[-1] if times else '?'}")
tools={}
prev=None
for r in rows:
    m=r.get('message') or {}
    role=m.get('role') or r.get('type')
    content=m.get('content')
    t=ts(r)
    if isinstance(content,str): content=[{'type':'text','text':content}]
    if not isinstance(content,list): content=[]
    for c in content:
        if not isinstance(c,dict): continue
        ty=c.get('type')
        if ty=='text' and role=='user':
            txt=c['text'].strip()
            if txt and not txt.startswith('<system-reminder'):
                print(f"[USER {t}] {txt[:600]}")
        elif ty=='text' and role=='assistant':
            txt=c['text'].strip()
            if re.search(r"\b(actually|wait|instead|my mistake|I was wrong|let me retry|retry|correction|oops|hmm, )\b",txt,re.I):
                print(f"[ASST-signal {t}] {txt[:400]}")
        elif ty=='tool_use':
            nm=c.get('name'); tools[nm]=tools.get(nm,0)+1
            inp=json.dumps(c.get('input'))[:200]
            if prev and t and (t-prev).total_seconds()>60:
                print(f"[GAP {(t-prev).total_seconds():.0f}s before {nm}] {inp[:160]}")
            prev=t
        elif ty=='tool_result':
            res=c.get('content')
            s=json.dumps(res)[:500] if not isinstance(res,str) else res[:500]
            if c.get('is_error') or 'tool_use_error' in s or 'Error:' in s or 'error' in s.lower()[:200]:
                print(f"[ERR {t}] {s[:350]}")
print("TOOLS:",sorted(tools.items(),key=lambda x:-x[1])[:12])

